static void z_t1844_destroy(z_t1844_t* p) {
    if (!p) return;
    for (uint32_t i = 0; i < p->length; i++) {
        z_t1784_destroy(&p->entries[i].value);
    }
    free(p->indices);
    free(p->entries);
    /* NO free(p) -- the struct is on the stack */
}
